    "\tdiscipline VARCHAR(16) NOT NULL, \n"
    "\tstatus VARCHAR(16) NOT NULL, \n"
    "\toperation VARCHAR(80) NOT NULL, \n"
    "\twrite_tier VARCHAR(4) NOT NULL, \n"
    "\tauthority_snapshot JSONB NOT NULL, \n"
    "\tshared_proof_id UUID NOT NULL, \n"
    "\tshared_proof_revision INTEGER NOT NULL, \n"
    "\tproof_consumed_at TIMESTAMP WITH TIME ZONE NOT NULL, \n"
    "\tproof_expires_at TIMESTAMP WITH TIME ZONE, \n"
    "\ttoken_sha256 VARCHAR(64) NOT NULL, \n"
    "\tmaterial_sha256 VARCHAR(64) NOT NULL, \n"
    "\tread_set_sha256 VARCHAR(64) NOT NULL, \n"
    "\tproduct_id UUID NOT NULL, \n"
    "\tproject_id UUID NOT NULL, \n"
    "\trevision INTEGER NOT NULL, \n"
    "\towner_id UUID NOT NULL, \n"
    "\twriter_id UUID NOT NULL, \n"
    "\tactor_id UUID NOT NULL, \n"
    "\trequester_id UUID NOT NULL, \n"
    "\tvisibility VARCHAR(16) NOT NULL, \n"
    "\tpurpose TEXT NOT NULL, \n"
    "\tbody JSONB NOT NULL, \n"
    "\tbody_sha256 VARCHAR(64) NOT NULL, \n"
    "\tmaterial_snapshot JSONB NOT NULL, \n"
    "\tinput_snapshot JSONB NOT NULL, \n"
    "\tsource_basis JSONB NOT NULL, \n"
    "\trequired_source_read_set JSONB NOT NULL, \n"
    "\tsources JSONB NOT NULL, \n"
    "\tcommand_id UUID NOT NULL, \n"
    "\treceipt_id UUID NOT NULL, \n"
    "\tintent_digest VARCHAR(64) NOT NULL, \n"
    "\trequest_digest VARCHAR(64) NOT NULL, \n"
    "\tid UUID NOT NULL, \n"
    "\ttenant_id UUID NOT NULL, \n"
    "\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n"
    "\tcategory_id UUID NOT NULL, \n"
    "\tPRIMARY KEY (id), \n"
    "\tFOREIGN KEY(tenant_id, category_id, product_id) REFERENCES products (tenant_id, category_id, "
    "id), \n"
    "\tFOREIGN KEY(tenant_id, product_id, project_id) REFERENCES projects (tenant_id, product_id, "
    "id), \n"
    "\tCHECK (visibility IN ('private','category','audience')), \n"
    "\tUNIQUE (tenant_id, id), \n"
    "\tUNIQUE (tenant_id, product_id, id, revision), \n"
    "\tUNIQUE (tenant_id, receipt_id), \n"
    "\tUNIQUE (tenant_id, command_id), \n"
    "\tUNIQUE (tenant_id, product_id, actor_id, operation, intent_digest), \n"
    "\tFOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id), \n"
    "\tFOREIGN KEY(tenant_id, writer_id) REFERENCES principals (tenant_id, id), \n"
    "\tFOREIGN KEY(tenant_id, actor_id) REFERENCES principals (tenant_id, id), \n"
    "\tFOREIGN KEY(tenant_id, requester_id) REFERENCES principals (tenant_id, id), \n"
    "\tFOREIGN KEY(tenant_id, receipt_id) REFERENCES action_receipts (tenant_id, id) DEFERRABLE "
    "INITIALLY DEFERRED, \n"
    "\tCHECK (writer_id=actor_id), \n"
    "\tCHECK (jsonb_typeof(body)='object' AND jsonb_typeof(material_snapshot)='object' AND "
    "jsonb_typeof(input_snapshot)='object' AND jsonb_typeof(source_basis)='object' AND "
    "jsonb_typeof(required_source_read_set)='array' AND "
    "jsonb_array_length(required_source_read_set)>0 AND jsonb_typeof(sources)='array' AND "
    "jsonb_array_length(sources)>0), \n"
    "\tCHECK (body_sha256 ~ '^[a-f0-9]{64}$' AND intent_digest ~ '^[a-f0-9]{64}$' AND request_digest "
    "~ '^[a-f0-9]{64}$'), \n"
    "\tUNIQUE (tenant_id, category_id, product_id, project_id, package_id, package_revision, "
    "discipline), \n"
    "\tUNIQUE (tenant_id, shared_proof_id), \n"
    "\tFOREIGN KEY(tenant_id, category_id, product_id, project_id, package_id, package_revision, "
    "visibility) REFERENCES release_packages (tenant_id, category_id, product_id, project_id, id, "
    "revision, visibility), \n"
    "\tFOREIGN KEY(tenant_id, shared_proof_id) REFERENCES confirmations (tenant_id, id) DEFERRABLE "
    "INITIALLY DEFERRED, \n"
    "\tCHECK (revision=1 AND package_revision>0 AND shared_proof_revision>0), \n"
    "\tCHECK (actor_id=requester_id AND writer_id=actor_id AND owner_id=requester_id), \n"
    "\tCHECK (write_tier='T2' AND status='approved'), \n"
    "\tCHECK ((discipline='engineering' AND operation='release.engineering.approve') OR "
    "(discipline='manufacturing' AND operation='release.manufacturing.approve')), \n"
    "\tCHECK (proof_consumed_at<=created_at AND (proof_expires_at IS NULL OR "
    "created_at<proof_expires_at)), \n"
    "\tCHECK (token_sha256 ~ '^[a-f0-9]{64}$' AND material_sha256 ~ '^[a-f0-9]{64}$' AND "
    "read_set_sha256 ~ '^[a-f0-9]{64}$')\n"
    ")\n"
    "\n",
    "CREATE INDEX ix_release_decisions_category_id ON release_decisions (category_id)",
    "CREATE INDEX ix_release_decisions_tenant_id ON release_decisions (tenant_id)",
    "CREATE FUNCTION public.assert_release_members(t uuid,target uuid,kind text) RETURNS void\n"
    "LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $release$\n"
    "\n"
    "DECLARE v record; r public.action_receipts; c public.confirmations;\n"
    " event_name text; expected_status text; proof uuid;\n"
    "BEGIN\n"
    " IF kind='release_package' THEN\n"
    "  SELECT * INTO STRICT v FROM public.release_packages WHERE tenant_id=t AND id=target;\n"
    "  event_name='release.package_assembled'; expected_status='assembled'; proof=NULL;\n"
    " ELSIF kind='release_decision' THEN\n"
    "  SELECT * INTO STRICT v FROM public.release_decisions WHERE tenant_id=t AND id=target;\n"
    "  event_name=CASE v.discipline WHEN 'engineering' THEN 'release.engineering_approved' ELSE "
    "'release.manufacturing_approved' END;\n"
    "  expected_status='approved'; proof=v.shared_proof_id;\n"
    "  SELECT * INTO STRICT c FROM public.confirmations WHERE tenant_id=t AND id=proof;\n"
    "  IF "
    "ROW(c.category_id,c.product_id,c.actor_id,c.subject_type,c.subject_id,c.operation,c.revision)\n"
    "    IS DISTINCT FROM "
    "ROW(v.category_id,v.product_id,v.actor_id,'product'::varchar,v.product_id,v.operation,v.shared_proof_revision)\n"
    "   OR c.consumed IS DISTINCT FROM true OR c.token_hash IS DISTINCT FROM v.token_sha256\n"
    "   OR c.payload_digest IS DISTINCT FROM v.material_sha256\n"
    "   OR c.snapshot IS DISTINCT FROM v.input_snapshot->'review'\n"
    "   OR c.expires_at IS DISTINCT FROM v.proof_expires_at\n"
    "   OR NOT(c.created_at<=v.proof_consumed_at AND v.proof_consumed_at<=v.created_at\n"
    "    AND (c.expires_at IS NULL OR v.created_at<c.expires_at)) THEN\n"
    "   RAISE EXCEPTION 'Release decision requires its original consumed T2 proof' USING "
    "ERRCODE='23514';\n"
    "  END IF;\n"
    " ELSE RAISE EXCEPTION 'Unknown release subject' USING ERRCODE='23514'; END IF;\n"
    " SELECT * INTO STRICT r FROM public.action_receipts WHERE tenant_id=t AND id=v.receipt_id;\n"
    " IF "
    "ROW(r.category_id,r.product_id,r.command_id,r.confirmation_id,r.actor_id,r.requester_id,r.operation,\n"
    "   "
    "r.subject_type,r.subject_id,r.subject_revision,r.visibility,r.request_digest,r.intent_digest)\n"
    "  IS DISTINCT FROM "
    "ROW(v.category_id,v.product_id,v.command_id,proof,v.actor_id,v.requester_id,v.operation,\n"
    "   kind::varchar,v.id,v.revision,v.visibility,v.request_digest,v.intent_digest)\n"
    "  OR r.result IS DISTINCT FROM "
    "jsonb_build_object('id',v.id,'revision',v.revision,'status',expected_status)\n"
    "  OR r.created_at<v.created_at\n"
    "  OR (kind='release_decision' AND (r.run_id IS NOT NULL OR r.agent_run_id IS NOT NULL\n"
    "    OR (c.expires_at IS NOT NULL AND r.created_at>=c.expires_at)))\n"
    "  OR (SELECT count(*) FROM public.action_receipts x WHERE x.tenant_id=t AND "
    "x.operation=v.operation\n"
    "   AND x.subject_type=kind AND x.subject_id=v.id AND x.subject_revision=v.revision)<>1\n"
    "  OR (SELECT count(*) FROM public.audit_entries x WHERE x.tenant_id=t AND x.receipt_id=r.id)<>1\n"
    "  OR NOT EXISTS(SELECT 1 FROM public.audit_entries a WHERE a.tenant_id=t AND a.receipt_id=r.id\n"
    "   AND a.category_id=v.category_id AND a.actor_id=v.actor_id AND a.operation=v.operation AND "
    "a.created_at>=v.created_at)\n"
    "  OR (SELECT count(*) FROM public.outbox_events x WHERE x.tenant_id=t AND x.receipt_id=r.id)<>1\n"
    "  OR NOT EXISTS(SELECT 1 FROM public.outbox_events e WHERE e.tenant_id=t AND e.receipt_id=r.id\n"
    "   AND e.category_id=v.category_id AND e.actor_id=v.actor_id AND e.type=event_name\n"
    "   AND e.subject_id=v.id AND e.subject_revision=v.revision AND e.schema_version=1\n"
    "   AND e.correlation_id=coalesce(r.agent_run_id,r.run_id,v.command_id) AND "
    "e.created_at>=v.created_at)\n"
    "  OR v.input_snapshot->>'original_key_sha256' IS NULL\n"
    "  OR v.input_snapshot->>'original_key_sha256' !~ '^[a-f0-9]{64}$'\n"
    "  OR (v.input_snapshot->'command') ? 'idempotency_key'\n"
    "  OR (v.input_snapshot->'command'->'payload') ? 'approval_token'\n"
    "  OR (v.input_snapshot->'semantic') ? 'approval_token'\n"
    "  OR NOT EXISTS(SELECT 1 FROM public.request_keys k WHERE k.tenant_id=t AND "
    "k.category_id=v.category_id\n"
    "   AND k.receipt_id=r.id AND k.actor_id=v.actor_id AND k.digest=v.request_digest\n"
    "   AND encode(sha256(convert_to(k.key,'UTF8')),'hex')=v.input_snapshot->>'original_key_sha256') "
    "THEN\n"
    "  RAISE EXCEPTION 'Release original receipt audit event or request mismatch' USING "
    "ERRCODE='23514';\n"
    " END IF;\n"
    "END;\n"
    "$release$",
    "CREATE FUNCTION public.assert_release_common(t uuid,target uuid,kind text) RETURNS void\n"
    "LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $release$\n"
    "\n"
    "DECLARE v record; r public.action_receipts; vx xid; rx xid; command jsonb; semantic jsonb; "
    "review jsonb; ref jsonb;\n"
    "BEGIN\n"
    " IF kind='release_package' THEN\n"
    "  SELECT x.*,x.xmin AS tx INTO STRICT v FROM public.release_packages x WHERE x.tenant_id=t AND "
    "x.id=target;\n"
    " ELSIF kind='release_decision' THEN\n"
    "  SELECT x.*,x.xmin AS tx INTO STRICT v FROM public.release_decisions x WHERE x.tenant_id=t AND "
    "x.id=target;\n"
    " ELSE RAISE EXCEPTION 'Unknown release subject' USING ERRCODE='23514'; END IF;\n"
    " vx=v.tx;\n"
    " SELECT * INTO STRICT r FROM public.action_receipts WHERE tenant_id=t AND id=v.receipt_id;\n"
    " SELECT xmin INTO rx FROM public.action_receipts WHERE tenant_id=t AND id=v.receipt_id;\n"
    " PERFORM public.assert_release_members(t,target,kind);\n"
    " command=v.input_snapshot->'command'; semantic=v.input_snapshot->'semantic'; "
    "review=v.input_snapshot->'review';\n"
    " IF v.actor_id IS DISTINCT FROM public.scope_actor() OR v.requester_id IS DISTINCT FROM "
    "public.scope_requester()\n"
    "  OR v.writer_id<>v.actor_id OR NOT public.category_access(t,v.category_id,true)\n"
    "  OR NOT EXISTS(SELECT 1 FROM public.principals p WHERE p.tenant_id=t AND p.id=v.actor_id AND "
    "p.active)\n"
    "  OR NOT EXISTS(SELECT 1 FROM public.principals p WHERE p.tenant_id=t AND p.id=v.requester_id "
    "AND p.kind='human' AND p.active)\n"
    "  OR (v.actor_id<>v.requester_id AND r.run_id IS NULL AND r.agent_run_id IS NULL)\n"
    "  OR (v.visibility='private' AND v.owner_id<>v.requester_id)\n"
    "  OR vx IS DISTINCT FROM rx\n"
    "  OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(v.input_snapshot) key)\n"
    "    IS DISTINCT FROM ARRAY['command','original_key_sha256','review','semantic']\n"
    "  OR command->>'operation' IS DISTINCT FROM v.operation\n"
    "  OR command->>'command_id' IS DISTINCT FROM v.command_id::text\n"
    "  OR command->>'category_id' IS DISTINCT FROM v.category_id::text\n"
    "  OR command->>'product_id' IS DISTINCT FROM v.product_id::text\n"
    "  OR command->'payload' IS DISTINCT FROM semantic\n"
    "  OR NOT COALESCE(command->'source_read_set' @> v.required_source_read_set,false)\n"
    "  OR NOT COALESCE(v.required_source_read_set @> command->'source_read_set',false)\n"
    "  OR "
    "jsonb_array_length(command->'source_read_set')<>jsonb_array_length(v.required_source_read_set)\n"
    "  OR review->>'operation' IS DISTINCT FROM v.operation\n"
    "  OR review->'required_source_read_set' IS DISTINCT FROM v.required_source_read_set\n"
    "  OR review->'read_basis' IS DISTINCT FROM v.source_basis\n"
    "  OR v.body->'scope' IS DISTINCT FROM "
    "jsonb_build_object('tenant_id',t,'product_id',v.product_id,'project_id',v.project_id)\n"
    "  OR v.body->>'category_id' IS DISTINCT FROM v.category_id::text\n"
    "  OR v.material_snapshot->'scope' IS DISTINCT FROM v.body->'scope'\n"
    "  OR v.material_snapshot->>'category_id' IS DISTINCT FROM v.category_id::text\n"
    "  OR NOT EXISTS(SELECT 1 FROM public.products p WHERE p.tenant_id=t AND "
    "p.category_id=v.category_id\n"
    "   AND p.id=v.product_id AND p.revision::text=command->>'expected_revision')\n"
    "  OR NOT EXISTS(SELECT 1 FROM public.projects p WHERE p.tenant_id=t AND "
    "p.category_id=v.category_id\n"
    "   AND p.product_id=v.product_id AND p.id=v.project_id)\n"
    "  OR NOT "
    "public.direct_source_set_visible(t,v.category_id,v.product_id,v.required_source_read_set)\n"
    "  OR EXISTS(SELECT 1 FROM public.audit_entries x WHERE x.tenant_id=t AND "
    "x.receipt_id=v.receipt_id AND x.xmin IS DISTINCT FROM vx)\n"
    "  OR EXISTS(SELECT 1 FROM public.outbox_events x WHERE x.tenant_id=t AND "
    "x.receipt_id=v.receipt_id AND x.xmin IS DISTINCT FROM vx)\n"
    "  OR NOT EXISTS(SELECT 1 FROM public.request_keys k WHERE k.tenant_id=t AND "
    "k.receipt_id=v.receipt_id\n"
    "   AND k.actor_id=v.actor_id AND k.digest=v.request_digest AND k.xmin=vx\n"
    "   AND encode(sha256(convert_to(k.key,'UTF8')),'hex')=v.input_snapshot->>'original_key_sha256') "
    "THEN\n"
    "  RAISE EXCEPTION 'Release requires actual scope and one common transaction' USING "
    "ERRCODE='23514';\n"
    " END IF;\n"
    " IF EXISTS(SELECT 1 FROM jsonb_array_elements(v.material_snapshot->'required_source_read_set') "
    "x\n"
    "   WHERE NOT v.required_source_read_set @> jsonb_build_array(x))\n"
    "  OR (SELECT count(DISTINCT x->>'artifact_id') FROM "
    "jsonb_array_elements(v.required_source_read_set) x)\n"
    "   <>jsonb_array_length(v.required_source_read_set) THEN\n"
    "  RAISE EXCEPTION 'Release must retain the actual material read set' USING ERRCODE='23514'; END "
    "IF;\n"
    " FOR ref IN SELECT value FROM jsonb_array_elements(v.required_source_read_set) LOOP\n"
    "  IF jsonb_typeof(ref->'expected_revision') IS DISTINCT FROM 'number'\n"
    "   OR NOT EXISTS(SELECT 1 FROM public.artifact_versions a WHERE a.tenant_id=t AND "
    "a.category_id=v.category_id\n"
    "    AND a.id::text=ref->>'artifact_id' AND a.revision::text=ref->>'expected_revision' AND "
    "a.status='active'\n"
    "    AND (v.visibility='private' OR a.visibility<>'private')\n"
    "    AND (a.original_id IS NULL OR EXISTS(SELECT 1 FROM public.uploaded_originals o\n"
    "     JOIN public.original_security sec ON sec.tenant_id=o.tenant_id AND sec.original_id=o.id\n"
    "     WHERE o.tenant_id=t AND o.category_id=v.category_id AND o.id=a.original_id AND "
    "o.status='parsed'\n"
    "      AND sec.source_state='active' AND sec.disposition='active'\n"
    "      AND (v.visibility='private' OR o.visibility<>'private')))) THEN\n"
    "   RAISE EXCEPTION 'Release direct original version security or audience changed' USING "
    "ERRCODE='23514'; END IF;\n"
    " END LOOP;\n"
    "END;\n"
    "$release$",
    "CREATE FUNCTION public.assert_release_package(t uuid,target uuid) RETURNS void\n"
    "LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $release$\n"
    "\n"
    "DECLARE v public.release_packages; cur public.release_package_currents; command jsonb; vx xid; "
    "cx xid;\n"
    "BEGIN\n"
    " SELECT * INTO STRICT v FROM public.release_packages WHERE tenant_id=t AND id=target;\n"
    " SELECT xmin INTO vx FROM public.release_packages WHERE tenant_id=t AND id=target;\n"
    " PERFORM public.assert_release_common(t,target,'release_package');\n"
    " command=v.input_snapshot->'command';\n"
    " SELECT * INTO STRICT cur FROM public.release_package_currents WHERE tenant_id=t\n"
    "  AND category_id=v.category_id AND product_id=v.product_id AND project_id=v.project_id AND "
    "series_id=v.series_id;\n"
    " SELECT xmin INTO cx FROM public.release_package_currents WHERE tenant_id=t AND id=cur.id;\n"
    " IF cur.version_id<>v.id OR cur.revision<>v.revision OR cur.epoch<>v.revision OR cx IS DISTINCT "
    "FROM vx\n"
    "  OR v.body IS DISTINCT FROM v.input_snapshot->'review'->'after'\n"
    "  OR v.body->'declaration' IS DISTINCT FROM v.input_snapshot->'semantic'\n"
    "  OR v.body->>'owner_id' IS DISTINCT FROM v.owner_id::text\n"
    "  OR v.body->>'product_revision' IS DISTINCT FROM command->>'expected_revision'\n"
    "  OR v.body->'sources' IS DISTINCT FROM v.sources\n"
    "  OR v.body->'required_source_read_set' IS DISTINCT FROM v.required_source_read_set\n"
    "  OR v.body->'objects' IS DISTINCT FROM v.material_snapshot->'objects'\n"
    "  OR v.body->'policy' IS DISTINCT FROM v.material_snapshot->'policy'\n"
    "  OR v.body->'checks' IS DISTINCT FROM v.material_snapshot->'checks'\n"
    "  OR v.body->'exceptions' IS DISTINCT FROM v.material_snapshot->'exceptions'\n"
    "  OR v.body->'declaration'->>'purpose' IS DISTINCT FROM v.purpose\n"
    "  OR v.body->'declaration'->>'visibility' IS DISTINCT FROM v.visibility\n"
    "  OR v.body->'declaration'->>'project_id' IS DISTINCT FROM v.project_id::text\n"
    "  OR v.material_snapshot->>'purpose' IS DISTINCT FROM v.purpose\n"
    "  OR v.body->'declaration'->'subject_config' IS DISTINCT FROM "
    "v.material_snapshot->'subject_config'\n"
    "  OR v.body->'declaration'->'release_scope' IS DISTINCT FROM "
    "v.material_snapshot->'release_scope'\n"
    "  OR (v.revision=1 AND (v.input_snapshot->'semantic'->'previous'<>'null'::jsonb\n"
    "    OR v.input_snapshot->'review'->'before'<>'null'::jsonb))\n"
    "  OR (v.revision>1 AND (v.input_snapshot->'semantic'->'previous'\n"
    "    IS DISTINCT FROM jsonb_build_object('id',v.previous_id,'revision',v.previous_revision)\n"
    "    OR v.input_snapshot->'review'->'before'->'version'->>'id' IS DISTINCT FROM "
    "v.previous_id::text\n"
    "    OR v.input_snapshot->'review'->'before'->'version'->>'revision' IS DISTINCT FROM "
    "v.previous_revision::text)) THEN\n"
    "  RAISE EXCEPTION 'Release package must fix its actual material and Current atom' USING "
    "ERRCODE='23514';\n"
    " END IF;\n"
    "END;\n"
    "$release$",
    "CREATE FUNCTION public.assert_release_decision(t uuid,target uuid) RETURNS void\n"
    "LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $release$\n"
    "\n"
    "DECLARE v public.release_decisions; p public.release_packages; c public.confirmations;\n"
    " vx xid; cx xid; authority jsonb; ref jsonb; review jsonb;\n"
    "BEGIN\n"
    " SELECT * INTO STRICT v FROM public.release_decisions WHERE tenant_id=t AND id=target;\n"
    " SELECT xmin INTO vx FROM public.release_decisions WHERE tenant_id=t AND id=target;\n"
    " SELECT * INTO STRICT p FROM public.release_packages WHERE tenant_id=t AND id=v.package_id;\n"
    " SELECT * INTO STRICT c FROM public.confirmations WHERE tenant_id=t AND id=v.shared_proof_id;\n"
    " SELECT xmin INTO cx FROM public.confirmations WHERE tenant_id=t AND id=v.shared_proof_id;\n"
    " PERFORM public.assert_release_common(t,target,'release_decision');\n"
    " authority=v.authority_snapshot; review=v.input_snapshot->'review';\n"
    " IF v.actor_id<>v.requester_id OR vx IS DISTINCT FROM cx\n"
    "  OR NOT EXISTS(SELECT 1 FROM public.principals a WHERE a.tenant_id=t AND a.id=v.actor_id AND "
    "a.kind='human' AND a.active)\n"
    "  OR NOT EXISTS(SELECT 1 FROM public.release_package_currents cur WHERE cur.tenant_id=t\n"
    "    AND cur.category_id=v.category_id AND cur.product_id=v.product_id AND "
    "cur.project_id=v.project_id\n"
    "    AND cur.series_id=p.series_id AND cur.version_id=p.id AND cur.revision=p.revision)\n"
    "  OR v.shared_proof_revision::text IS DISTINCT FROM "
    "v.input_snapshot->'command'->>'expected_revision'\n"
    "  OR v.body->>'operation' IS DISTINCT FROM v.operation OR v.body->>'discipline' IS DISTINCT FROM "
    "v.discipline\n"
    "  OR v.body->'package' IS DISTINCT FROM jsonb_build_object('id',p.id,'revision',p.revision)\n"
    "  OR v.body->>'package_sha256' IS DISTINCT FROM p.body->>'body_sha256'\n"
    "  OR (v.body||jsonb_build_object('prepared_at',null)) IS DISTINCT FROM review->'after'\n"
    "  OR v.body->'input_snapshot' IS DISTINCT FROM v.input_snapshot->'semantic'\n"
    "  OR v.body->'signers' IS DISTINCT FROM jsonb_build_array(v.actor_id)\n"
    "  OR v.body->>'purpose' IS DISTINCT FROM v.purpose\n"
    "  OR v.body->'customer_acceptance' IS DISTINCT FROM 'null'::jsonb\n"
    "  OR v.body->'external_received' IS DISTINCT FROM 'false'::jsonb\n"
    "  OR v.body->'external_effective' IS DISTINCT FROM 'false'::jsonb\n"
    "  OR v.body->'assessment'->>'discipline' IS DISTINCT FROM v.discipline\n"
    "  OR NOT COALESCE(v.body->'assessment'->>'state' IN ('READY','READY_WITH_CONDITIONS'),false)\n"
    "  OR v.body->'assessment'->'blocked' IS DISTINCT FROM '[]'::jsonb\n"
    "  OR v.body->'assessment'->'unknown' IS DISTINCT FROM '[]'::jsonb\n"
    "  OR (v.body->>'expiry' IS NOT NULL AND v.created_at>=(v.body->>'expiry')::timestamptz)\n"
    "  OR review->'authority' IS DISTINCT FROM authority\n"
    "  OR authority->'scope' IS DISTINCT FROM v.body->'scope'\n"
    "  OR authority->>'subject_id' IS DISTINCT FROM v.actor_id::text\n"
    "  OR authority->>'operation' IS DISTINCT FROM v.operation\n"
    "  OR authority->>'purpose' IS DISTINCT FROM v.purpose\n"
    "  OR authority->'authorized' IS DISTINCT FROM 'true'::jsonb\n"
    "  OR authority->'qualified' IS DISTINCT FROM 'true'::jsonb\n"
    "  OR NOT(authority->'roles' @> jsonb_build_array(v.discipline))\n"
    "  OR NOT public.capture_authority_time_current(authority,v.created_at)\n"
    "  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(authority->'fact_refs')) THEN\n"
    "  RAISE EXCEPTION 'Release decision requires the exact package and independent named authority' "
    "USING ERRCODE='23514';\n"
    " END IF;\n"
    " FOR ref IN SELECT value FROM jsonb_array_elements(authority->'fact_refs') LOOP\n"
    "  IF NOT EXISTS(SELECT 1 FROM public.professional_authority_current cur WHERE cur.tenant_id=t\n"
    "   AND cur.category_id=v.category_id AND cur.product_id=v.product_id AND "
    "cur.project_id=v.project_id\n"
    "   AND cur.subject_id=v.actor_id AND cur.fact_id::text=ref->>'id' AND "
    "cur.fact_revision::text=ref->>'revision'\n"
    "   AND cur.series_id::text=ref->>'series_id' AND cur.kind=ref->>'kind' AND "
    "cur.epoch::text=ref->>'epoch') THEN\n"
    "   RAISE EXCEPTION 'Release named authority Current changed' USING ERRCODE='23514'; END IF;\n"
    " END LOOP;\n"
    "END;\n"
    "$release$",
    "CREATE FUNCTION public.protect_release_current() RETURNS trigger\n"
    "LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $release$\n"
    "\n"
    "BEGIN\n"
    " IF TG_OP='INSERT' THEN\n"
    "  IF NEW.revision=1 AND NEW.epoch=1 AND NEW.version_id=NEW.series_id THEN RETURN NEW; END IF;\n"
    " ELSIF TG_OP='UPDATE' THEN\n"
    "  IF (to_jsonb(NEW)-ARRAY['version_id','revision','epoch']) IS NOT DISTINCT FROM\n"
    "    (to_jsonb(OLD)-ARRAY['version_id','revision','epoch'])\n"
    "   AND NEW.revision=OLD.revision+1 AND NEW.epoch=OLD.epoch+1\n"
    "   AND EXISTS(SELECT 1 FROM public.release_packages v WHERE v.tenant_id=NEW.tenant_id AND "
    "v.id=NEW.version_id\n"
    "    AND v.category_id=NEW.category_id AND v.product_id=NEW.product_id AND "
    "v.project_id=NEW.project_id\n"
    "    AND v.series_id=NEW.series_id AND v.owner_id=NEW.owner_id AND v.visibility=NEW.visibility\n"
    "    AND v.revision=NEW.revision AND v.previous_id=OLD.version_id AND "
    "v.previous_revision=OLD.revision) THEN RETURN NEW;\n"
    "  END IF;\n"
    " END IF;\n"
    " RAISE EXCEPTION 'Release Current advances one exact package and epoch' USING ERRCODE='23514';\n"
    "END;\n"
    "$release$",
    "CREATE FUNCTION public.require_release_current() RETURNS trigger\n"
    "LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $release$\n"
    "\n"
    "DECLARE cur public.release_package_currents; cx xid;\n"
    "BEGIN\n"
    " SELECT * INTO STRICT cur FROM public.release_package_currents WHERE tenant_id=NEW.tenant_id AND "
    "id=NEW.id;\n"
    " SELECT xmin INTO cx FROM public.release_package_currents WHERE tenant_id=NEW.tenant_id AND "
    "id=NEW.id;\n"
    " IF NOT EXISTS(SELECT 1 FROM public.release_packages p WHERE p.tenant_id=cur.tenant_id\n"
    "  AND p.category_id=cur.category_id AND p.product_id=cur.product_id AND "
    "p.project_id=cur.project_id\n"
    "  AND p.series_id=cur.series_id AND p.owner_id=cur.owner_id AND p.visibility=cur.visibility\n"
    "  AND p.id=cur.version_id AND p.revision=cur.revision AND p.xmin=cx) THEN\n"
    "  RAISE EXCEPTION 'Release Current requires its package in the same transaction' USING "
    "ERRCODE='23514';\n"
    " END IF;\n"
    " RETURN NULL;\n"
    "END;\n"
    "$release$",
    "CREATE FUNCTION public.protect_release_proof() RETURNS trigger\n"
    "LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $release$\n"
    "\n"
    "DECLARE old_scoped boolean=false; new_scoped boolean=false;\n"
    "BEGIN\n"
    " IF TG_OP<>'INSERT' THEN old_scoped=OLD.operation IN "
    "('release.engineering.approve','release.manufacturing.approve'); END IF;\n"
    " IF TG_OP<>'DELETE' THEN new_scoped=NEW.operation IN "
    "('release.engineering.approve','release.manufacturing.approve'); END IF;\n"
    " IF old_scoped OR new_scoped THEN\n"
    "  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Release proof history is retained' USING "
    "ERRCODE='23514';\n"
    "  ELSIF TG_OP='INSERT' THEN\n"
    "   IF NEW.consumed IS DISTINCT FROM false THEN RAISE EXCEPTION 'Release proof starts unconsumed' "
    "USING ERRCODE='23514'; END IF;\n"
    "  ELSIF NOT(old_scoped AND new_scoped) OR OLD.consumed IS DISTINCT FROM false OR NEW.consumed IS "
    "DISTINCT FROM true\n"
    "   OR (to_jsonb(NEW)-'consumed') IS DISTINCT FROM (to_jsonb(OLD)-'consumed') THEN\n"
    "   RAISE EXCEPTION 'Release proof permits only original false to true' USING ERRCODE='23514';\n"
    "  END IF;\n"
    " END IF;\n"
    " IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;\n"
    "END;\n"
    "$release$",
    "CREATE FUNCTION public.require_release_transition() RETURNS trigger\n"
    "LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $release$\n"
    "\n"
    "BEGIN\n"
    " IF NEW.operation IN ('release.engineering.approve','release.manufacturing.approve') THEN\n"
    "  IF OLD.consumed IS DISTINCT FROM false OR NEW.consumed IS DISTINCT FROM true\n"
    "   OR (SELECT count(*) FROM public.release_decisions v WHERE v.tenant_id=NEW.tenant_id\n"
    "    AND v.shared_proof_id=NEW.id AND v.operation=NEW.operation)<>1 THEN\n"
    "   RAISE EXCEPTION 'Consumed release proof requires one actual named decision' USING "
    "ERRCODE='23514'; END IF;\n"
    " END IF;\n"
    " RETURN NULL;\n"
    "END;\n"
    "$release$",
    "CREATE FUNCTION public.protect_release_receipt() RETURNS trigger\n"
    "LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $release$\n"
    "\n"
    "DECLARE scoped boolean=false;\n"
    "BEGIN\n"
    " IF TG_OP<>'INSERT' THEN scoped=OLD.operation IN "
    "('release.package.assemble','release.engineering.approve','release.manufacturing.approve') OR "
    "OLD.subject_type IN ('release_package','release_decision'); END IF;\n"
    " IF TG_OP<>'DELETE' THEN scoped=scoped OR NEW.operation IN "
    "('release.package.assemble','release.engineering.approve','release.manufacturing.approve') OR "
    "NEW.subject_type IN ('release_package','release_decision'); END IF;\n"
    " IF scoped AND TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Release receipt is immutable' USING "
    "ERRCODE='23514'; END IF;\n"
    " IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;\n"
    "END;\n"
    "$release$",
    "CREATE FUNCTION public.protect_release_member() RETURNS trigger\n"
    "LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $release$\n"
    "\n"
    "DECLARE scoped boolean=false; old_scoped boolean=false;\n"
    "BEGIN\n"
    " IF TG_OP<>'DELETE' THEN\n"
    "  SELECT EXISTS(SELECT 1 FROM public.action_receipts r WHERE r.tenant_id=NEW.tenant_id AND "
    "r.id=NEW.receipt_id\n"
    "   AND (r.operation IN "
    "('release.package.assemble','release.engineering.approve','release.manufacturing.approve') OR "
    "r.subject_type IN ('release_package','release_decision'))) INTO scoped;\n"
    " END IF;\n"
    " IF TG_OP<>'INSERT' THEN\n"
    "  SELECT EXISTS(SELECT 1 FROM public.action_receipts r WHERE r.tenant_id=OLD.tenant_id AND "
    "r.id=OLD.receipt_id\n"
    "   AND (r.operation IN "
    "('release.package.assemble','release.engineering.approve','release.manufacturing.approve') OR "
    "r.subject_type IN ('release_package','release_decision'))) INTO old_scoped;\n"
    " END IF;\n"
    " IF TG_OP<>'INSERT' AND (scoped OR old_scoped) THEN\n"
    "  IF TG_OP='UPDATE' AND TG_TABLE_NAME='outbox_events'\n"
    "   AND (to_jsonb(NEW)-ARRAY['delivered_at','lease_id','lease_until','attempts','last_error']) IS "
    "NOT DISTINCT FROM\n"
    "    (to_jsonb(OLD)-ARRAY['delivered_at','lease_id','lease_until','attempts','last_error']) THEN "
    "RETURN NEW; END IF;\n"
    "  RAISE EXCEPTION 'Release original audit event or request is immutable' USING ERRCODE='23514';\n"
    " END IF;\n"
    " IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;\n"
    "END;\n"
    "$release$",
    "CREATE FUNCTION public.require_release_member() RETURNS trigger\n"
    "LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $release$\n"
    "\n"
    "DECLARE r public.action_receipts;\n"
    "BEGIN\n"
    " IF TG_TABLE_NAME='action_receipts' THEN r=NEW;\n"
    " ELSE SELECT * INTO r FROM public.action_receipts WHERE tenant_id=NEW.tenant_id AND "
    "id=NEW.receipt_id; END IF;\n"
    " IF r.operation IN "
    "('release.package.assemble','release.engineering.approve','release.manufacturing.approve') OR "
    "r.subject_type IN ('release_package','release_decision') THEN\n"
    "  PERFORM public.assert_release_members(r.tenant_id,r.subject_id,r.subject_type::text);\n"
    " END IF;\n"
    " RETURN NULL;\n"
    "END;\n"
    "$release$",
    "CREATE FUNCTION public.require_release_package() RETURNS trigger\n"
    "LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $release$\n"
    "BEGIN PERFORM public.assert_release_package(NEW.tenant_id,NEW.id); RETURN NULL; END;\n"
    "$release$",
    "CREATE FUNCTION public.require_release_decision() RETURNS trigger\n"
    "LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $release$\n"
    "BEGIN PERFORM public.assert_release_decision(NEW.tenant_id,NEW.id); RETURN NULL; END;\n"
    "$release$",
    "CREATE FUNCTION public.reject_release_mutation() RETURNS trigger\n"
    "LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $release$\n"
    "BEGIN RAISE EXCEPTION 'Release package and named decision history is immutable' USING "
    "ERRCODE='23514'; END;\n"
    "$release$",
