    "(public.category_access(tenant_id,category_id,true) AND "
    "public.category_access(tenant_id,category_id) AND EXISTS(SELECT 1 FROM public.release_packages p "
    "WHERE p.tenant_id=release_package_currents.tenant_id AND "
    "p.category_id=release_package_currents.category_id AND "
    "p.product_id=release_package_currents.product_id AND "
    "p.project_id=release_package_currents.project_id AND p.id=release_package_currents.version_id "
    "AND p.revision=release_package_currents.revision))",
    'GRANT UPDATE(version_id,revision,epoch) ON public."release_package_currents" TO pdos_next_app',
    'ALTER TABLE public."release_decisions" ENABLE ROW LEVEL SECURITY',
    'ALTER TABLE public."release_decisions" FORCE ROW LEVEL SECURITY',
    'CREATE POLICY owner_internal ON public."release_decisions" TO pdos_next_owner USING (true) WITH '
    "CHECK (true)",
    'CREATE POLICY release_read ON public."release_decisions" FOR SELECT TO pdos_next_app USING '
    "(public.category_access(tenant_id,category_id) AND EXISTS(SELECT 1 FROM public.release_packages "
    "p WHERE p.tenant_id=release_decisions.tenant_id AND p.category_id=release_decisions.category_id "
    "AND p.product_id=release_decisions.product_id AND p.project_id=release_decisions.project_id AND "
    "p.id=release_decisions.package_id AND p.revision=release_decisions.package_revision) AND "
    "public.direct_source_set_visible(tenant_id,category_id,product_id,release_decisions.required_source_read_set))",
    'CREATE POLICY release_insert ON public."release_decisions" FOR INSERT TO pdos_next_app WITH '
    "CHECK (public.category_access(tenant_id,category_id,true) AND "
    "public.scope_actor()=public.scope_requester() AND EXISTS(SELECT 1 FROM public.principals a WHERE "
    "a.tenant_id=nullif(current_setting('pdos.tenant_id',true),'')::uuid AND "
    "a.id=public.scope_actor() AND a.kind='human' AND a.active) AND "
    "public.category_access(tenant_id,category_id) AND EXISTS(SELECT 1 FROM public.release_packages p "
    "WHERE p.tenant_id=release_decisions.tenant_id AND p.category_id=release_decisions.category_id "
    "AND p.product_id=release_decisions.product_id AND p.project_id=release_decisions.project_id AND "
    "p.id=release_decisions.package_id AND p.revision=release_decisions.package_revision) AND "
    "public.direct_source_set_visible(tenant_id,category_id,product_id,release_decisions.required_source_read_set))",
    'REVOKE ALL ON public."release_decisions" FROM '
    "PUBLIC,pdos_next_app,pdos_agent,pdos_next_auth,pdos_next_dispatch",
    'GRANT SELECT,INSERT ON public."release_decisions" TO pdos_next_app',
