    "$function$\n",
    "CREATE OR REPLACE FUNCTION public.m3_lifecycle_row_links(t uuid, c uuid, table_name text, "
    "payload jsonb)\n"
    " RETURNS uuid[]\n"
    " LANGUAGE plpgsql\n"
