    "  WHEN 'evidence_links' THEN ARRAY['target_id']\n"
    "  WHEN 'manufacturing_baseline_publications' THEN ARRAY['project_id']\n"
    "  WHEN 'manufacturing_publication_currents' THEN ARRAY['series_id']\n"
